{
  "title": "add-library-version-to-telemetry",
  "request": "Hey, could we include the Browser-Use package version in every telemetry event? I'd like a 'library_version' property added to the POSTHOG_EVENT_SETTINGS.",
  "edits": [
    {
      "path": "browser_use/telemetry/service.py",
      "search": "from browser_use.utils import singleton",
      "replace": "from browser_use.utils import singleton

def _get_library_version() -> str:
    """Return the installed browser-use package version, or 'unknown' if unavailable."""
    try:
        from importlib import metadata
        return metadata.version('browser-use')
    except Exception:
        return 'unknown'"
    },
    {
      "path": "browser_use/telemetry/service.py",
      "search": "POSTHOG_EVENT_SETTINGS = {
	'process_person_profile': True,
}",
      "replace": "POSTHOG_EVENT_SETTINGS = {
	'process_person_profile': True,
	'library_version': _get_library_version(),
}"
    }
  ],
  "test_path": "tests/test_telemetry_version.py",
  "test": "import importlib

def test_library_version_in_telemetry_settings():
    # Reload the module to ensure fresh evaluation
    module = importlib.import_module('browser_use.telemetry.service')
    importlib.reload(module)
    settings = getattr(module, 'POSTHOG_EVENT_SETTINGS')
    assert 'library_version' in settings
    version = settings['library_version']
    assert isinstance(version, str)
    assert version  # non-empty string"
}
